BEGIN;

CREATE TABLE IF NOT EXISTS tsk_pairs (
    id              BIGSERIAL PRIMARY KEY,
    from_ref        TEXT NOT NULL,            -- raw osis source verse, e.g. 'Gen.1.1'
    from_book_slug  TEXT NOT NULL,            -- resolved canon slug
    from_chapter    INT  NOT NULL,
    from_verse      INT  NOT NULL,
    to_ref          TEXT NOT NULL,            -- raw osis target (may be a range)
    votes           INT  NOT NULL DEFAULT 0,
    UNIQUE (from_ref, to_ref)
);
CREATE INDEX IF NOT EXISTS idx_tsk_source ON tsk_pairs(from_book_slug, from_chapter, from_verse);

ON CONFLICT (from_ref, to_ref) DO UPDATE SET votes=EXCLUDED.votes, from_book_slug=EXCLUDED.from_book_slug, from_chapter=EXCLUDED.from_chapter, from_verse=EXCLUDED.from_verse;

